-- The rate for each grade on a sheet: a percent with two decimals. A grade with no row has no rate.
CREATE TABLE rate (
    sheet_id VARCHAR(100)  NOT NULL REFERENCES sheet (id),
    grade    VARCHAR(1)    NOT NULL CHECK (grade IN ('A', 'B', 'C')),
    rate     DECIMAL(5, 2) NOT NULL CHECK (rate >= 0),
    PRIMARY KEY (sheet_id, grade)
);
-- A claim's due is fixed when it is settled: what was due on its amount at its person's grade's
-- rate at that moment. None while it is not settled, or when the grade had no rate then (its due
-- stays live).
ALTER TABLE claim ADD COLUMN settled_due DECIMAL(12, 2);
package net.officefloor.hq.app.rate;

import jakarta.validation.Valid;
import jakarta.validation.constraints.NotNull;
import jakarta.validation.constraints.Pattern;
import java.math.BigDecimal;
import java.util.List;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PutMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestHeader;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;

/** The rate for each grade on a sheet. */
@RestController
@RequestMapping("/api/sheets/{sheetId}/rates")
public class RateController {

    /** The rate is a percent, 0.00 or more, with up to two decimals. */
    public record RateForm(@NotNull @Pattern(regexp = "\\d{1,3}(\\.\\d{1,2})?") String rate) {}

    /** The rate is shown with two decimals. */
    public record RateView(String grade, String rate) {

        static RateView of(Rate rate) {
            return new RateView(rate.getGrade(), rate.getRate().setScale(2).toPlainString());
        }
    }

    private final RateService service;

    public RateController(RateService service) {
        this.service = service;
    }

    @GetMapping
    public List<RateView> list(@RequestHeader("X-User") String user, @PathVariable String sheetId) {
        return service.list(sheetId).stream().map(RateView::of).toList();
    }

    @PutMapping("/{grade:[ABC]}")
    public RateView set(@RequestHeader("X-User") String user, @PathVariable String sheetId,
            @PathVariable String grade, @Valid @RequestBody RateForm form) {
        return RateView.of(service.set(user, sheetId, grade, new BigDecimal(form.rate())));
    }
}
package net.officefloor.hq.app.rate;

import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.Id;
import jakarta.persistence.IdClass;
import jakarta.persistence.Table;
import java.io.Serializable;
import java.math.BigDecimal;
import java.util.Objects;

/** The rate for a grade on a sheet: a percent with two decimals. */
@Entity
@Table(name = "rate")
@IdClass(Rate.Key.class)
public class Rate {

    /** A rate is kept by its sheet and grade. */
    public static class Key implements Serializable {

        private String sheetId;
        private String grade;

        protected Key() {}

        public Key(String sheetId, String grade) {
            this.sheetId = sheetId;
            this.grade = grade;
        }

        @Override
        public boolean equals(Object o) {
            return o instanceof Key k && Objects.equals(sheetId, k.sheetId) && Objects.equals(grade, k.grade);
        }

        @Override
        public int hashCode() {
            return Objects.hash(sheetId, grade);
        }
    }

    @Id
    @Column(name = "sheet_id", nullable = false)
    private String sheetId;

    @Id
    @Column(name = "grade", nullable = false)
    private String grade;

    @Column(name = "rate", nullable = false, precision = 5, scale = 2)
    private BigDecimal rate;

    protected Rate() {}

    public Rate(String sheetId, String grade, BigDecimal rate) {
        this.sheetId = sheetId;
        this.grade = grade;
        this.rate = rate;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getGrade() {
        return grade;
    }

    public BigDecimal getRate() {
        return rate;
    }

    public void setRate(BigDecimal rate) {
        this.rate = rate;
    }
}
